# Write a function to find the maximum product formed by multiplying numbers of an increasing subsequence of that array.
def max_product(arr, n):
    mpis = [0] * (n)
    for i in range(n):
        mpis[i] = arr[i]
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and mpis[i] < (mpis[j] * arr[i]):
                mpis[i] = mpis[j] * arr[i]
    return max(mpis)

